//! Replays `tests/fixtures/strings/oracle.tsv` (generated by
//! `gen_oracle.php` under PHP 8.3 with mbstring) against this crate.
//!
//! Deprecations are not recorded (master adds several that 8.3 lacks).
//! Known, deliberate differences from 8.3 (php-src master behaviour) are
//! listed in `KNOWN_MASTER_DIFFS`.

use php_mbstring::state::SubstituteArg;
use php_mbstring::strings::StrstrVariant;
use php_mbstring::{EncodingList, HttpInput, MbError, MbState, SubstituteChar};
use std::fmt::Write as _;

#[derive(Debug, Clone, PartialEq)]
enum V {
    S(Vec<u8>),
    I(i64),
    B(bool),
    N,
    A(Vec<V>),
    E(String, String),
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn parse(s: &str) -> V {
    match s.as_bytes().first() {
        Some(b's') => V::S(unhex(&s[1..])),
        Some(b'i') => V::I(s[1..].parse().unwrap()),
        Some(b'T') => V::B(true),
        Some(b'F') => V::B(false),
        Some(b'N') => V::N,
        Some(b'A') => V::A(if s.len() == 1 { vec![] } else { s[1..].split(',').map(parse).collect() }),
        Some(b'E') => {
            let (cls, msg) = s[1..].split_once(':').unwrap();
            V::E(cls.to_string(), String::from_utf8(unhex(msg)).unwrap())
        }
        _ => panic!("bad value {s}"),
    }
}

fn s(v: &V) -> &[u8] {
    match v {
        V::S(b) => b,
        other => panic!("expected string, got {other:?}"),
    }
}
fn os(v: Option<&V>) -> Option<&[u8]> {
    match v {
        None | Some(V::N) => None,
        Some(V::S(b)) => Some(b),
        other => panic!("expected ?string, got {other:?}"),
    }
}
fn i(v: &V) -> i64 {
    match v {
        V::I(n) => *n,
        other => panic!("expected int, got {other:?}"),
    }
}
fn oi(v: Option<&V>) -> Option<i64> {
    match v {
        None | Some(V::N) => None,
        Some(V::I(n)) => Some(*n),
        other => panic!("expected ?int, got {other:?}"),
    }
}
fn b(v: &V) -> bool {
    matches!(v, V::B(true))
}

fn strs(v: &V) -> Vec<Vec<u8>> {
    match v {
        V::A(items) => items.iter().map(|x| s(x).to_vec()).collect(),
        other => panic!("expected array, got {other:?}"),
    }
}

fn err(e: &MbError, func: &str) -> V {
    V::E(e.class().to_string(), e.message_for(func))
}

fn bytes_or_false(r: Option<Vec<u8>>) -> V {
    r.map_or(V::B(false), V::S)
}

fn int_or_false(r: Option<i64>) -> V {
    r.map_or(V::B(false), V::I)
}

#[allow(clippy::too_many_lines)]
fn dispatch(st: &mut MbState, f: &str, a: &[V]) -> V {
    macro_rules! r {
        ($e:expr, $ok:expr) => {
            match $e {
                Ok(x) => $ok(x),
                Err(e) => err(&e, f),
            }
        };
    }
    let list_arg = |v: &V| -> (Option<Vec<Vec<u8>>>, Option<Vec<u8>>) {
        match v {
            V::A(_) => (Some(strs(v)), None),
            V::S(x) => (None, Some(x.clone())),
            _ => (None, None),
        }
    };
    match f {
        "mb_strlen" => r!(st.mb_strlen(s(&a[0]), os(a.get(1))), V::I),
        "mb_strwidth" => r!(st.mb_strwidth(s(&a[0]), os(a.get(1))), V::I),
        "mb_check_encoding" => r!(st.mb_check_encoding(s(&a[0]), os(a.get(1))), V::B),
        "mb_scrub" => r!(st.mb_scrub(s(&a[0]), os(a.get(1))), V::S),
        "mb_substr" => r!(st.mb_substr(s(&a[0]), i(&a[1]), oi(a.get(2)), os(a.get(3))), V::S),
        "mb_strcut" => r!(st.mb_strcut(s(&a[0]), i(&a[1]), oi(a.get(2)), os(a.get(3))), V::S),
        "mb_str_split" => r!(st.mb_str_split(s(&a[0]), i(&a[1]), os(a.get(2))), |v: Vec<Vec<u8>>| V::A(
            v.into_iter().map(V::S).collect()
        )),
        "mb_strtoupper" => r!(st.mb_strtoupper(s(&a[0]), os(a.get(1))), V::S),
        "mb_strtolower" => r!(st.mb_strtolower(s(&a[0]), os(a.get(1))), V::S),
        "mb_convert_case" => r!(st.mb_convert_case(s(&a[0]), i(&a[1]), os(a.get(2))), V::S),
        "mb_convert_encoding" => {
            let (arr, st_) = a.get(2).map_or((None, None), list_arg);
            let from = match (&arr, &st_) {
                (Some(x), _) => Some(EncodingList::Array(x)),
                (_, Some(x)) => Some(EncodingList::Str(x)),
                _ => None,
            };
            r!(st.mb_convert_encoding(s(&a[0]), s(&a[1]), from), bytes_or_false)
        }
        "mb_ord" => r!(st.mb_ord(s(&a[0]), os(a.get(1))), int_or_false),
        "mb_chr" => r!(st.mb_chr(i(&a[0]), os(a.get(1))), bytes_or_false),
        "mb_strimwidth" => r!(
            st.mb_strimwidth(s(&a[0]), i(&a[1]), i(&a[2]), a.get(3).map_or(&b""[..], s), os(a.get(4))),
            V::S
        ),
        "mb_strpos" => r!(st.mb_strpos(s(&a[0]), s(&a[1]), i(&a[2]), os(a.get(3))), int_or_false),
        "mb_strrpos" => r!(st.mb_strrpos(s(&a[0]), s(&a[1]), i(&a[2]), os(a.get(3))), int_or_false),
        "mb_stripos" => r!(st.mb_stripos(s(&a[0]), s(&a[1]), i(&a[2]), os(a.get(3))), int_or_false),
        "mb_strripos" => r!(st.mb_strripos(s(&a[0]), s(&a[1]), i(&a[2]), os(a.get(3))), int_or_false),
        "mb_strstr" | "mb_strrchr" | "mb_stristr" | "mb_strrichr" => {
            let v = match f {
                "mb_strstr" => StrstrVariant::Strstr,
                "mb_strrchr" => StrstrVariant::Strrchr,
                "mb_stristr" => StrstrVariant::Stristr,
                _ => StrstrVariant::Strrichr,
            };
            r!(st.mb_strstr_variant(v, s(&a[0]), s(&a[1]), b(&a[2]), os(a.get(3))), bytes_or_false)
        }
        "mb_substr_count" => r!(st.mb_substr_count(s(&a[0]), s(&a[1]), os(a.get(2))), V::I),
        "mb_substitute_character" => match a.first() {
            None => match st.mb_substitute_character_get() {
                SubstituteChar::None => V::S(b"none".to_vec()),
                SubstituteChar::Long => V::S(b"long".to_vec()),
                SubstituteChar::Entity => V::S(b"entity".to_vec()),
                SubstituteChar::Char(c) => V::I(i64::from(c)),
            },
            Some(V::S(x)) => r!(st.mb_substitute_character_set(SubstituteArg::Str(x)), V::B),
            Some(V::I(n)) => r!(st.mb_substitute_character_set(SubstituteArg::Int(*n)), V::B),
            other => panic!("{other:?}"),
        },
        "mb_detect_encoding" => {
            let (arr, st_) = a.get(1).map_or((None, None), list_arg);
            let l = match (&arr, &st_) {
                (Some(x), _) => Some(EncodingList::Array(x)),
                (_, Some(x)) => Some(EncodingList::Str(x)),
                _ => None,
            };
            let strict = a.get(2).map(b);
            r!(st.mb_detect_encoding(s(&a[0]), l, strict, false), |x: Option<&str>| x
                .map_or(V::B(false), |n| V::S(n.as_bytes().to_vec())))
        }
        "mb_encode_numericentity" | "mb_decode_numericentity" => {
            let map: Vec<Option<i64>> = match &a[1] {
                V::A(items) => items.iter().map(|x| Some(i(x))).collect(),
                other => panic!("{other:?}"),
            };
            if f == "mb_encode_numericentity" {
                r!(st.mb_encode_numericentity(s(&a[0]), &map, os(a.get(2)), a.get(3).is_some_and(b)), V::S)
            } else {
                r!(st.mb_decode_numericentity(s(&a[0]), &map, os(a.get(2))), V::S)
            }
        }
        "mb_encode_mimeheader" => r!(
            st.mb_encode_mimeheader(s(&a[0]), os(a.get(1)), os(a.get(2)), a.get(3).map_or(&b"\r\n"[..], s), a.get(4).map_or(0, i)),
            V::S
        ),
        "mb_decode_mimeheader" => V::S(st.mb_decode_mimeheader(s(&a[0]))),
        "mb_str_pad" => r!(st.mb_str_pad(s(&a[0]), i(&a[1]), s(&a[2]), i(&a[3]), os(a.get(4))), V::S),
        "mb_convert_kana" => r!(st.mb_convert_kana(s(&a[0]), os(a.get(1)), os(a.get(2))), V::S),
        "mb_preferred_mime_name" => r!(st.mb_preferred_mime_name(s(&a[0])), |x: Option<&str>| x
            .map_or(V::B(false), |n| V::S(n.as_bytes().to_vec()))),
        "mb_encoding_aliases" => r!(st.mb_encoding_aliases(s(&a[0])), |x: Vec<&str>| V::A(
            x.into_iter().map(|n| V::S(n.as_bytes().to_vec())).collect()
        )),
        "mb_internal_encoding" => match a.first() {
            None => V::S(st.mb_internal_encoding_get().as_bytes().to_vec()),
            Some(x) => r!(st.mb_internal_encoding_set(s(x)), V::B),
        },
        "mb_language" => match a.first() {
            None => V::S(st.mb_language_get().as_bytes().to_vec()),
            Some(x) => r!(st.mb_language_set(s(x)), V::B),
        },
        "mb_detect_order" => match a.first() {
            None => V::A(st.mb_detect_order_get().into_iter().map(|n| V::S(n.as_bytes().to_vec())).collect()),
            Some(x) => {
                let (arr, st_) = list_arg(x);
                let l = match (&arr, &st_) {
                    (Some(x), _) => EncodingList::Array(x),
                    (_, Some(x)) => EncodingList::Str(x),
                    _ => unreachable!(),
                };
                r!(st.mb_detect_order_set(l), V::B)
            }
        },
        "mb_http_output" => match a.first() {
            None => V::S(st.mb_http_output_get().as_bytes().to_vec()),
            Some(x) => r!(st.mb_http_output_set(s(x)), V::B),
        },
        "mb_http_input" => r!(st.mb_http_input(os(a.first())), |h| match h {
            HttpInput::False => V::B(false),
            HttpInput::Name(n) => V::S(n.into_bytes()),
            HttpInput::List(l) => V::A(l.into_iter().map(|n| V::S(n.as_bytes().to_vec())).collect()),
        }),
        "mb_regex_encoding" => match a.first() {
            None => V::S(st.mb_regex_encoding_get().as_bytes().to_vec()),
            Some(x) => r!(st.mb_regex_encoding_set(s(x)), V::B),
        },
        "mb_list_encodings" => V::A(
            php_mbstring::state::mb_list_encodings()
                .into_iter()
                .map(|n| V::S(n.as_bytes().to_vec()))
                .collect(),
        ),
        _ => panic!("unknown function {f}"),
    }
}

/// Cases where php-src master intentionally differs from PHP 8.3.
fn known_master_diff(f: &str, a: &[V]) -> bool {
    let enc = a.last().and_then(|v| if let V::S(x) = v { Some(x.as_slice()) } else { None });
    match f {
        // master's mb_strcut uses mb_cut_gb18030 / mb_cut_utf16* (with its
        // ineffective surrogate check) / mb_cut_utf8 (backs up over
        // continuation bytes even in invalid strings), and returns "" when
        // the computed length is 0.
        "mb_strcut" => {
            let len0 = match (&a[0], &a[1], a.get(2)) {
                (V::S(x), V::I(from), Some(V::I(len))) if *len < 0 => {
                    let l = i64::try_from(x.len()).unwrap();
                    let from = if *from < 0 { (l + from).max(0) } else { *from };
                    (l - from) + len <= 0
                }
                _ => false,
            };
            len0 || matches!(enc, Some(b"GB18030" | b"UTF-16" | b"UTF-16LE" | b"UTF-16BE"))
                || (enc == Some(b"UTF-8") && std::str::from_utf8(s(&a[0])).is_err())
        }
        // 8.3 moved the search window by the needle's *byte* length.
        "mb_strrpos" => i(&a[2]) < 0 && enc != Some(b"UTF-8"),
        // master emits no space between adjacent encoded words.
        "mb_decode_mimeheader" => true,
        // master: "must not be empty"; 8.3: "must be a non-empty string".
        "mb_str_pad" => true,
        // master adds GB18030-2022.
        "mb_list_encodings" => true,
        _ => false,
    }
}

fn show(v: &V) -> String {
    match v {
        V::S(b) => format!("{:?}", String::from_utf8_lossy(b)),
        other => format!("{other:?}"),
    }
}

#[test]
fn replay_string_function_oracle() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/strings/oracle.tsv");
    let data = std::fs::read_to_string(path).expect("fixture");
    let mut st = MbState::new();
    let mut failures = String::new();
    let mut nfail = 0usize;
    let mut total = 0usize;
    let mut per_func: std::collections::BTreeMap<String, usize> = Default::default();
    for (lineno, line) in data.lines().enumerate() {
        let parts: Vec<&str> = line.split('\t').collect();
        let f = parts[0];
        let eq = parts.iter().position(|p| p.starts_with('=')).unwrap();
        let args: Vec<V> = parts[1..eq].iter().filter(|p| !p.is_empty()).map(|p| parse(p)).collect();
        let args = if parts[1..eq].len() == 1 && parts[1].is_empty() { vec![] } else { args };
        let expected = parse(&parts[eq][1..]);
        let exp_diag: Vec<String> = parts
            .get(eq + 1)
            .filter(|d| !d.is_empty())
            .map(|d| d.split(',').map(|h| String::from_utf8(unhex(h)).unwrap()).collect())
            .unwrap_or_default();
        total += 1;
        let got = dispatch(&mut st, f, &args);
        let got_diag: Vec<String> = st
            .take_diagnostics()
            .into_iter()
            .filter(|d| d.level != php_mbstring::Level::Deprecated)
            .map(|d| d.message)
            .collect();
        if (got != expected || got_diag != exp_diag) && !known_master_diff(f, &args) {
            nfail += 1;
            *per_func.entry(f.to_string()).or_default() += 1;
            if nfail <= 40 {
                let _ = writeln!(
                    failures,
                    "line {}: {f}({}) => expected {} {exp_diag:?}, got {} {got_diag:?}",
                    lineno + 1,
                    args.iter().map(show).collect::<Vec<_>>().join(", "),
                    show(&expected),
                    show(&got)
                );
            }
        }
    }
    assert!(nfail == 0, "{nfail}/{total} oracle mismatches {per_func:?}:\n{failures}");
}
